namespace AirportSmith.Models;

// One user-authored <TaxiwaySign>. Not sim data: SimConnect's Facility Data
// API has no sign type at all (see requirements.md's Background, "Confirmed
// hard gap"), so every sign here was placed by hand or generated by
// TaxiwaySignPlanner. XMeters/ZMeters are a local-meters offset from the
// airport reference point — the same plane as TaxiParkingSpot.BiasXMeters/
// BiasZMeters — converted to the lat/lon bglcomp.xsd's ctTaxiwaySign wants
// only at export time (AirportXmlExporter).
//
// Label uses the SDK's sign grammar (see TaxiwaySignLabel). HeadingDeg and
// Justification are stored exactly as <TaxiwaySign> wants them, matching the
// Scenery Editor's own values: justification is the side of the taxiway the
// sign stands on, heading the reader's travel direction turned 90° toward
// the taxiway (+90 LEFT, −90 RIGHT; see TaxiwaySignPlanner.SignFacing).
// Project schema v2 files stored the plain travel direction; the v3 load
// migration in AirportProjectStore converts them.
//
// IsAutoPlaced marks a sign TaxiwaySignPlanner generated and the user hasn't
// touched since: re-running auto-placement replaces those and keeps every
// other sign. AnchorPointIndex is the taxi point an auto sign was generated
// for, so a "Generate for Selected Points" run only replaces the Auto signs
// of the points it was run for. Added after project schema v2 shipped: an
// older project file has no TaxiwaySigns list at all and loads an empty one
// (AirportDetails' initializer); Size's initializer keeps a sign with no
// stored size at the Scenery Editor's default.
public class TaxiwaySign
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public double XMeters { get; set; }
    public double ZMeters { get; set; }
    public double HeadingDeg { get; set; }
    public string Label { get; set; } = string.Empty;
    public TaxiwaySignJustification Justification { get; set; }
    public TaxiwaySignSize Size { get; set; } = TaxiwaySignSize.Size3;
    public bool IsAutoPlaced { get; set; }
    public int? AnchorPointIndex { get; set; }
}

// bglcomp.xsd's stSide, as used by ctTaxiwaySign's justification.
public enum TaxiwaySignJustification
{
    Left = 0,
    Right = 1,
}

// bglcomp.xsd's stSignSize (SIZE1..SIZE5). No 0 member: the Scenery Editor
// has no "no size", and TaxiwaySign.Size's initializer covers a missing value.
public enum TaxiwaySignSize
{
    Size1 = 1,
    Size2 = 2,
    Size3 = 3,
    Size4 = 4,
    Size5 = 5,
}
